from pathlib import Path
import base64, zlib, subprocess

PATCH_B64 = """"""
patch = zlib.decompress(base64.b64decode(PATCH_B64))
subprocess.run(["patch", "-p1"], input=patch, check=True)

main = Path("payload-installer/main.c").read_text()
makefile = Path("payload-installer/Makefile").read_text()
assert 'TAYSON_PAYLOAD_VERSION "0.2.0"' in main
assert 'TAYSONP/1 DIRECTRESUME' in main
assert 'download_direct' in main
assert 'CACHE_META' in main
assert 'PAYLOAD_WORKER_STACK' in main
assert 'Tayson-Payload-Installer-0.2.0' in makefile
